        by_tag[out["tag"]] = by_tag.get(out["tag"], 0) + 1

    return {
        "items": clean_items,
        "errors": errors,
        "stats": {
            "lines": len(lines),
            "valid": valid,
            "kept": len(clean_items),
            "duplicates": duplicates,
            "errors": len(errors),
            "by_tag": by_tag,
